<script setup lang="tsx">
import { computed, WatchStopHandle } from "vue";
import { onBeforeUnmount, onMounted, ref, watch } from "vue";
import { useRoute, useRouter } from "vue-router";
import { useCurrentInstance } from "@/util";
import { GetCommonErrorCode, ShowErrorTips, ShowTextTipsInfo } from "@/util/tips";
import { ProblemAttemptStatus, GetProblemDailyList, ParseProblemDaily } from "@/apis/problem.ts";
import { ProblemTag, ProblemDaily, ProblemDailyView } from "@/types/problem.ts";
import { AuthType } from "@/auth";
import { useUserStore } from "@/stores/user.ts";
import type { TableRowData, TNodeReturnValue } from "tdesign-vue-next";
import type { CellParams } from "@/types/table";
import { useBreakpoint } from "@/composables/useBreakpoint";

const route = useRoute();
const router = useRouter();
const { globalProperties } = useCurrentInstance();
const userStore = useUserStore();
const { isMobile } = useBreakpoint();

let viewActive = false;
let watchHandle: WatchStopHandle | null = null;

let tagsMap = {} as { [key: number]: ProblemTag };
let problemAttemptStatus = {} as { [key: string]: ProblemAttemptStatus };

const hasEditAuth = computed(() => {
  return userStore.hasAuth(AuthType.ManageProblem);
});

// 说明：tdesign 的 BaseTableCol<T> 是递归类型（children?: BaseTableCol<T>[]），本页 cell 返回 JSX，
// 直接标注会触发 TS2589（Type instantiation is excessively deep），故按其字段构造一个非递归的等价列类型
type ProblemDailyListColumn = {
  title: string;
  colKey: string;
  cell?: (_h: unknown, data: CellParams<TableRowData>) => TNodeReturnValue;
};

const listColumns = ref<ProblemDailyListColumn[]>([
  {
    title: "日期",
    colKey: "key",
    cell: (_h: unknown, data: CellParams<TableRowData>) => {
      return (
        <t-button variant="dashed" onClick={() => handleGotoProblem(data.row.key)}>
          {data.row.key}
        </t-button>
      );
    },
  },
  {
    title: "问题标识",
    colKey: "problemKey",
    cell: (_h: unknown, data: CellParams<TableRowData>) => {
      const theme = getProblemIdTheme(data.row.problemId);
      return (
        <t-button variant="dashed" theme={theme} onClick={() => handleGotoProblem(data.row.key)}>
          {data.row.problemKey}
        </t-button>
      );
    },
  },
  {
    title: "标题",
    colKey: "title",
    cell: (_h: unknown, data: CellParams<TableRowData>) => {
      return (
        <t-button variant="text" onClick={() => handleGotoProblem(data.row.key)}>
          {data.row.title}
        </t-button>
      );
    },
  },
  {
    title: "标签",
    colKey: "tags",
    cell: (_h: unknown, data: CellParams<TableRowData>) => {
      const tags = data.row.tags;
      if (!tags || tags.length === 0) {
        return "";
      }
      const tagButtons = [];
      for (let i = 0; i < tags.length; i++) {
        const tag = tags[i];
        tagButtons.push(
          <t-button key={i} theme="default" variant="outline" size="small" onClick={() => handleClickTag(tag)}>
            {tag.name}
          </t-button>
        );
      }
      return <t-space>{tagButtons}</t-space>;
    },
  },
  {
    title: "正确",
    colKey: "accept",
  },
  {
    title: "提交",
    colKey: "attempt",
  },
]);

const dataLoading = ref(false);

let currentPage = 1;
let currentPageSize = 50;

const pagination = ref({
  current: currentPage,
  pageSize: currentPageSize,
  defaultCurrent: currentPage,
  defaultPageSize: currentPageSize,
  total: 0,
  pageSizeOptions: [50, 100],
});

const problemViews = ref<ProblemDailyView[]>([]);

const searchProblemForm = ref({
  date: [] as string[],
  problemKey: "",
});

const handleGotoProblem = (key: string) => {
  if (!key) {
    return;
  }
  router.push({
    name: "problem-daily-detail",
    params: {
      dailyId: key,
    },
  });
};

const getProblemIdTheme = (id: string) => {
  if (!id) {
    return "default";
  }
  if (!problemAttemptStatus) {
    return "default";
  }
  const status = problemAttemptStatus[id];
  if (!status) {
    return "default";
  }
  switch (status) {
    case ProblemAttemptStatus.Accept:
      return "success";
    case ProblemAttemptStatus.Attempt:
      return "warning";
    default:
      return "default";
  }
};

const handleClickSearch = async () => {
  let dateStr = "";
  if (searchProblemForm.value.date && searchProblemForm.value.date.length > 1) {
    dateStr = searchProblemForm.value.date[0] + "~" + searchProblemForm.value.date[1];
  }
  // 更新 URL 查询参数
  await router.push({
    query: {
      ...route.query,
      date: dateStr,
      problem_key: searchProblemForm.value.problemKey,
      page: 1,
      page_size: pagination.value.defaultPageSize,
    },
  });
};

const handleClickReset = async () => {
  searchProblemForm.value.date = [];
  searchProblemForm.value.problemKey = "";
  // 更新 URL 查询参数
  await router.push({
    query: {
      ...route.query,
      date: "",
      problem_key: "",
      page: 1,
      page_size: pagination.value.defaultPageSize,
    },
  });
};

// 移动端筛选 Drawer 显隐状态
const showFilterDrawer = ref(false);

// 当前已激活的筛选条件数量，用于「筛选」按钮徽标提示
const activeFilterCount = computed(() => {
  let count = 0;
  if (searchProblemForm.value.date && searchProblemForm.value.date.length > 0) count++;
  if (searchProblemForm.value.problemKey) count++;
  return count;
});

// 移动端 Drawer 中的搜索：复用桌面端逻辑，搜索后关闭抽屉
const handleDrawerSearch = async () => {
  await handleClickSearch();
  showFilterDrawer.value = false;
};

// 移动端 Drawer 中的重置：复用桌面端逻辑
const handleDrawerReset = async () => {
  await handleClickReset();
};

const handleClickTag = (tag: ProblemTag) => {
  if (!tag) {
    return;
  }
  router.push({
    name: "problem-list",
    query: {
      ...route.query,
      title: "",
      tag: tag.name,
      page: 1,
      page_size: pagination.value.defaultPageSize,
    },
  });
};

const handleClickCreate = () => {
  router.push({ name: "manage-problem-daily-create" });
};

const fetchData = async (paginationInfo: { current: number; pageSize: number }, needLoading: boolean) => {
  if (needLoading) {
    dataLoading.value = true;
  }
  try {
    const { current, pageSize } = paginationInfo;
    let startDate = "";
    if (searchProblemForm.value.date[0]) {
      startDate = searchProblemForm.value.date[0];
    }
    let endDate = "";
    if (searchProblemForm.value.date[1]) {
      endDate = searchProblemForm.value.date[1];
    }
    const res = await GetProblemDailyList(startDate, endDate, searchProblemForm.value.problemKey, current, pageSize);
    problemViews.value = [];
    if (res.code === 0) {
      let responseList = [] as ProblemDaily[];
      if (res.data) {
        responseList = res.data.list as ProblemDaily[];
      }
      if (!responseList || responseList.length <= 0) {
        pagination.value = { ...pagination.value, total: 0 };
        problemAttemptStatus = {};
        ShowTextTipsInfo(globalProperties, "未找到记录");
        return;
      }
      tagsMap = {};
      if (res.data.tags) {
        res.data.tags.forEach((tag: ProblemTag) => {
          tagsMap[tag.id] = tag;
        });
      }
      responseList.forEach((item: ProblemDaily) => {
        const result = ParseProblemDaily(item, tagsMap);
        problemViews.value?.push(result);
      });
      pagination.value = { ...pagination.value, total: res.data.total_count };
      problemAttemptStatus = res.data.attempt_status;
    } else {
      if (needLoading) {
        ShowErrorTips(globalProperties, res.code);
      }
    }
  } catch (err) {
    console.error(err);
    if (needLoading) {
      ShowErrorTips(globalProperties, GetCommonErrorCode());
    }
  } finally {
    if (needLoading) {
      dataLoading.value = false;
    }
  }
};

const onPageChange = async (pageInfo: { current: number; pageSize: number }) => {
  // 更新 URL 查询参数
  await router.push({
    query: { ...route.query, page: pageInfo.current, page_size: pageInfo.pageSize },
  });
};

// 初始化分页信息
onMounted(async () => {
  viewActive = true;

  dataLoading.value = true;

  watchHandle = watch(
    () => route.query,
    (newQuery) => {
      if (!viewActive) {
        return;
      }
      searchProblemForm.value.date = [];
      if (newQuery.date) {
        const dateRange = (newQuery.date as string).split("~");
        if (dateRange.length === 2) {
          searchProblemForm.value.date = [dateRange[0], dateRange[1]];
        }
      }
      searchProblemForm.value.problemKey = (newQuery.problem_key as string) || "";
      const queryPage = parseInt(newQuery.page as string) || pagination.value.defaultCurrent;
      const queryPageSize = parseInt(newQuery.page_size as string) || pagination.value.defaultPageSize;
      currentPage = queryPage;
      currentPageSize = queryPageSize;
      pagination.value = { ...pagination.value, current: currentPage, pageSize: currentPageSize };
      fetchData({ current: currentPage, pageSize: currentPageSize }, true);
    },
    { immediate: true }
  );
});

onBeforeUnmount(() => {
  viewActive = false;

  if (watchHandle) {
    watchHandle();
  }
});
</script>

<template>
  <!-- 移动端布局：顶部操作栏 + 列表 + 右侧筛选 Drawer -->
  <div v-if="isMobile" class="problem-daily-list-mobile">
    <div class="mobile-toolbar">
      <t-button
        theme="default"
        variant="outline"
        class="mobile-toolbar-btn"
        @click="showFilterDrawer = true"
      >
        <template #icon>
          <t-icon name="filter" />
        </template>
        筛选
        <t-badge
          v-if="activeFilterCount > 0"
          :count="activeFilterCount"
          shape="round"
          color="var(--td-brand-color)"
          :offset="[6, -6]"
        />
      </t-button>
      <t-button v-if="hasEditAuth" theme="primary" class="mobile-toolbar-btn" @click="handleClickCreate">
        <template #icon>
          <t-icon name="add" />
        </template>
        新建
      </t-button>
    </div>

    <t-card class="mobile-list-card">
      <div style="overflow-x: auto; width: 100%">
        <t-table
          :data="problemViews"
          :columns="listColumns"
          row-key="key"
          vertical-align="top"
          :hover="true"
          :pagination="pagination"
          table-layout="auto"
          :loading="dataLoading"
          @page-change="onPageChange"
        />
      </div>
    </t-card>

    <!-- 移动端筛选抽屉：复用桌面端筛选表单 -->
    <t-drawer
      v-model:visible="showFilterDrawer"
      header="筛选"
      placement="right"
      size="80%"
      :close-on-esc-keydown="true"
      :show-overlay="true"
    >
      <t-form :model="searchProblemForm" @submit="handleDrawerSearch" @reset="handleDrawerReset">
        <t-form-item label="日期" label-align="top">
          <t-date-range-picker v-model="searchProblemForm.date" allow-input clearable format="YYYY-MM-DD" style="width: 100%" />
        </t-form-item>
        <t-form-item label="问题" label-align="top">
          <t-input v-model="searchProblemForm.problemKey" placeholder="请输入问题标识" clearable></t-input>
        </t-form-item>
      </t-form>

      <!-- 每日一题说明：移动端放入 Drawer 底部 -->
      <t-divider align="left">每日一题</t-divider>
      <p class="mobile-daily-tip">由管理员团队精选的题目，每日0点更新。</p>
      <p class="mobile-daily-tip">当日下午6点提供题解，次日提供AC代码。</p>

      <template #footer>
        <t-space>
          <t-button theme="primary" @click="handleDrawerSearch">确定</t-button>
          <t-button theme="danger" variant="outline" @click="handleDrawerReset">重置</t-button>
        </t-space>
      </template>
    </t-drawer>
  </div>

  <!-- 桌面端布局：左右双栏，筛选在右侧 -->
  <t-row v-else>
    <t-col :span="9">
      <t-card style="margin: 10px">
        <div style="overflow-x: auto; width: 100%">
          <t-table
            :data="problemViews"
            :columns="listColumns"
            row-key="key"
            vertical-align="top"
            :hover="true"
            :pagination="pagination"
            table-layout="auto"
            :loading="dataLoading"
            @page-change="onPageChange"
          />
        </div>
      </t-card>
    </t-col>
    <t-col :span="3">
      <div style="margin: 10px">
        <div v-if="hasEditAuth" class="dida-operation-container">
          <t-space>
            <t-button @click="handleClickCreate">新建</t-button>
          </t-space>
        </div>
        <t-card class="sh-card">
          <t-form :model="searchProblemForm" @submit="handleClickSearch" @reset="handleClickReset">
            <t-form-item label="日期" label-align="top">
              <t-date-range-picker v-model="searchProblemForm.date" allow-input clearable format="YYYY-MM-DD" />
            </t-form-item>
            <t-form-item label="问题" label-align="top">
              <t-input v-model="searchProblemForm.problemKey" placeholder="请输入问题标识" clearable></t-input>
            </t-form-item>
            <t-form-item label-align="top">
              <t-space>
                <t-button theme="primary" type="submit">搜索</t-button>
                <t-button theme="danger" type="reset">重置</t-button>
              </t-space>
            </t-form-item>
          </t-form>
        </t-card>

        <t-card class="sh-card" header="每日一题" :header-bordered="true">
          <p>由管理员团队精选的题目，每日0点更新。</p>
          <p>当日下午6点提供题解，次日提供AC代码。</p>
        </t-card>
      </div>
    </t-col>
  </t-row>
</template>

<style scoped>
.sh-card {
  margin: 10px;
}

.sh-background-black {
  background-color: #212121;
}

.sh-tag-button {
  margin: 2px;
}

.dida-operation-container {
  margin: 10px 0 20px;
  text-align: right;
}

/* 移动端列表页样式 */
.problem-daily-list-mobile {
  padding: 10px;
}

.mobile-toolbar {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 10px;
}

/* 工具栏按钮平分剩余空间 */
.mobile-toolbar-btn {
  flex: 1;
}

.mobile-list-card {
  margin: 0;
}

.mobile-daily-tip {
  margin: 8px 0;
  font-size: 13px;
  color: var(--td-text-color-secondary);
  line-height: 1.6;
}
</style>
